def norm(v):
    v=np.asarray(v,float); n=np.linalg.norm(v)
    return v/n if n>1e-12 else v
def rot(v,axis,ang):
    axis=norm(axis); v=np.asarray(v,float)
    return v*np.cos(ang)+np.cross(axis,v)*np.sin(ang)+axis*np.dot(axis,v)*(1-np.cos(ang))
atoms=[]; bonds=set()
def add(el,xyz):
    atoms.append((el,np.asarray(xyz,float))); return len(atoms)-1
def bond(a,b):
    bonds.add((min(a,b),max(a,b)))

def add_methyl(attach,d,bondlen=1.54):
    d=norm(d); C=attach+bondlen*d; iC=add('C',C); bond(iC,-999)  # placeholder no
    ref=np.array([0.,0.,1.]);
    if abs(np.dot(d,ref))>0.9: ref=np.array([1.,0.,0.])
    p=norm(np.cross(d,ref))
    for k in range(3):
        hd=(1/3)*d+(2*np.sqrt(2)/3)*rot(p,d,k*2*np.pi/3)
        add('H',C+1.09*norm(hd))
    return iC
def add_methine(attach,d,bondlen=1.85):
    d=norm(d); M=attach+bondlen*d; iM=add('C',M)
